def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.170.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.169.0"' not in init:
        sys.exit("ABORT: not at v3.169.0.")
    for k in ("payroll_function", "statutory"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("PAY1", LESSONS_P1, QUESTIONS_P1, 9) + _validate("PAY2", LESSONS_P2, QUESTIONS_P2, 10)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("PAY 1", LESSONS_P1, QUESTIONS_P1, "payroll_function",
         "The pay machinery in ZhiftERP: the seven-step pipeline and the custody split; the Employee record's payroll fields (Salary Mode, bank details under custody rules, Payroll Cost Center, Holiday List); the Salary Component's flags and Accounts table; the Salary Structure as the package template with the B/H/T split; the Salary Structure Assignment carrying the Base, From Date, and Income Tax Slab link with the supersession rule; formulas, conditions, and payment-days proration; and the preview procedure with its five reads."),
        ("PAY 2", LESSONS_P2, QUESTIONS_P2, "statutory",
         "The statutory layer in ZhiftERP: the custody frame and the division of authority; the Income Tax Slab built from the accountant's table with the PAYE component's taxable-salary flag and the plausibility check; pension's two shares on the B/H/T family with per-PFA schedules; NHF and the levies from the applicability register; the state-of-residence PAYE split; account wiring proven by the posting read and the monthly payroll tie; the six-step remittance workflow with the zero check; and the Salary Register — one monthly record, derived schedules, confidentiality enforced."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.169.0"', '"3.170.0"'))
    print("  data: PAYROLL 1 + 2 lessons + banks REPLACED (style v3, product-first)")
    print("wrote __version__ -> 3.170.0")


if __name__ == "__main__":
    main()
